package thaumcraft.verification;

import com.google.gson.*;
import com.mojang.blaze3d.vertex.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import org.joml.Matrix4f;
import org.joml.Vector3f;
import thaumcraft.client.model.*;

/** Native model against unchanged original bytecode, plus actual GPU/registered renderer checks. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientWardenVerification {
    private static boolean done;
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception{
        if(done||!"warden-client".equals(System.getProperty("thaumcraft.r3.phase")))return;
        var mc=net.minecraft.client.Minecraft.getInstance();if(!(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen)||mc.getOverlay()!=null)return;done=true;
        var path=Path.of(System.getProperty("thaumcraft.r3.root"));var result=new JsonObject();var checks=new ArrayList<String>();
        try{
            var reference=JsonParser.parseString(Files.readString(path.resolve("analysis/full_port/original-warden-model.json"))).getAsJsonObject();var originals=reference.getAsJsonObject("parts");
            var root=GuardianMesh.create().bakeRoot();var model=new GuardianModel<thaumcraft.entities.EldritchWarden>(root);var parts=new LinkedHashMap<String,ModelPart>();for(String name:originals.keySet())parts.put(name,find(name,originals,root));
            require(parts.size()==54,"all54 original Guardian/Warden parts baked",checks);
            for(var entry:originals.entrySet()){
                var expected=entry.getValue().getAsJsonObject();var part=parts.get(entry.getKey());var pivot=expected.getAsJsonArray("pivot");var rotation=expected.getAsJsonArray("rotation");for(int i=0;i<3;i++){near(new float[]{part.x,part.y,part.z}[i],pivot.get(i).getAsFloat(),"original pivot "+entry.getKey());near(new float[]{part.xRot,part.yRot,part.zRot}[i],rotation.get(i).getAsFloat(),"original rotation "+entry.getKey());}require(true,"original pivot/rotation "+entry.getKey(),checks);
                parts.values().forEach(p->p.visible=false);part.visible=true;part.x=part.y=part.z=part.xRot=part.yRot=part.zRot=0;var capture=new Capture();part.render(new PoseStack(),capture,240,OverlayTexture.NO_OVERLAY);compare(capture.vertices,expected.getAsJsonArray("boxes").get(0).getAsJsonObject().getAsJsonArray("vertices"),new Matrix4f());require(true,"24 unchanged original MC cube vertices/UVs "+entry.getKey(),checks);part.resetPose();parts.values().forEach(p->p.visible=true);
            }
            var animate=GuardianModel.class.getDeclaredMethod("animate",int.class,float.class,float.class,float.class,float.class,float.class);animate.setAccessible(true);var opacity=GuardianModel.class.getDeclaredField("alpha");opacity.setAccessible(true);opacity.setFloat(model,1);
            for(var entry:reference.getAsJsonArray("cases")){
                var row=entry.getAsJsonObject();animate.invoke(model,row.get("ticks").getAsInt(),row.get("partial").getAsFloat(),row.get("left").getAsFloat(),row.get("right").getAsFloat(),row.get("yaw").getAsFloat(),row.get("pitch").getAsFloat());var angles=row.getAsJsonObject("rotation");for(var bone:parts.entrySet()){var expected=angles.getAsJsonArray(bone.getKey());near(bone.getValue().xRot,expected.get(0).getAsFloat(),"animated X "+bone.getKey());near(bone.getValue().yRot,expected.get(1).getAsFloat(),"animated Y "+bone.getKey());near(bone.getValue().zRot,expected.get(2).getAsFloat(),"animated Z "+bone.getKey());}require(true,"original integer tick/partial and arm animation",checks);
                var capture=new Capture();model.renderToBuffer(new PoseStack(),capture,240,OverlayTexture.NO_OVERLAY,-1);if(row.get("warden").getAsBoolean()){var pose=new PoseStack();pose.scale(1.01f,1.01f,1.01f);model.renderEye(pose,capture,(int)row.get("eye_light").getAsFloat(),OverlayTexture.NO_OVERLAY);require(capture.light==(int)row.get("eye_light").getAsFloat(),"original additive eye light pulse",checks);}
                var draws=row.getAsJsonArray("draws");require(capture.vertices.size()==draws.size()*24,"source ordered body/eye draw count",checks);int offset=0;for(var name:draws){String bone=name.getAsString();var expected=originals.getAsJsonObject(bone);var matrix=transform(bone,originals,angles);if(bone.equals("HoodEye"))matrix=new Matrix4f().scale(1.01f).mul(matrix);compare(capture.vertices.subList(offset,offset+24),expected.getAsJsonArray("boxes").get(0).getAsJsonObject().getAsJsonArray("vertices"),matrix);offset+=24;}require(true,"complete original ordered body/child/eye geometry and UVs",checks);
                var pose=new PoseStack();pose.translate(0,0,-100);var texture=ResourceLocation.parse("thaumcraft:textures/models/eldritch_warden.png");model.renderToBuffer(pose,mc.renderBuffers().bufferSource().getBuffer(RenderType.entityTranslucent(texture)),240,OverlayTexture.NO_OVERLAY,-1);mc.renderBuffers().bufferSource().endBatch();require(org.lwjgl.opengl.GL11.glGetError()==0,"native Warden body GPU draw",checks);
            }
            var dispatcherField=net.minecraft.client.renderer.entity.EntityRenderDispatcher.class.getDeclaredField("renderers");dispatcherField.setAccessible(true);var registered=(Map<?,?>)dispatcherField.get(mc.getEntityRenderDispatcher());require(registered.get(thaumcraft.entities.R5Entities.ELDRITCH_WARDEN.get()).getClass().getName().endsWith("EldritchWardenRenderer"),"Warden renderer registered with native dispatcher",checks);
            var meshClass=Class.forName("thaumcraft.client.OriginalObjMesh");var meshGet=meshClass.getDeclaredMethod("get",String.class);meshGet.setAccessible(true);var hemis=meshGet.invoke(null,"hemis");var draw=meshClass.getDeclaredMethod("renderParticles",PoseStack.class,VertexConsumer.class,int.class,int.class);draw.setAccessible(true);var typeField=Class.forName("thaumcraft.client.WardenClientEffects").getDeclaredField("SONIC");typeField.setAccessible(true);var type=(net.minecraft.client.particle.ParticleRenderType)typeField.get(null);
            for(int frame=1;frame<=15;frame++){var pose=new PoseStack();pose.translate(0,0,-100);var capture=new Capture();draw.invoke(hemis,pose,capture,frame,220);require(!capture.vertices.isEmpty()&&capture.vertices.size()%8==0,"original hemisphere has paired front/back quads",checks);for(var v:capture.vertices){for(int i=0;i<5;i++)if(!Float.isFinite(v[i]))throw new AssertionError("Nonfinite sonic vertex");if(v[4]<(frame-1)/15f-1e-6||v[4]>frame/15f+1e-6)throw new AssertionError("Sonic frame escaped original atlas slice");}require(capture.light==220,"source sonic light220",checks);var builder=type.begin(Tesselator.getInstance(),mc.getTextureManager());draw.invoke(hemis,pose,builder,frame,220);BufferUploader.drawWithShader(builder.buildOrThrow());require(org.lwjgl.opengl.GL11.glGetError()==0,"native sonic hemisphere/frame GPU draw "+frame,checks);}
            com.mojang.blaze3d.systems.RenderSystem.depthMask(true);com.mojang.blaze3d.systems.RenderSystem.disableBlend();com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();
            result.addProperty("passed",true);result.addProperty("driver",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));
        }catch(Throwable failure){result.addProperty("passed",false);result.addProperty("error",failure.toString());failure.printStackTrace();}
        var hashes=new JsonObject();for(String resource:List.of("thaumcraft/client/model/GuardianModel.class","thaumcraft/client/model/GuardianMesh.class","thaumcraft/client/EldritchWardenRenderer.class","thaumcraft/client/EldritchWardenRenderer$1.class","thaumcraft/client/WardenClientEffects.class","thaumcraft/client/WardenClientEffects$Smoke.class","thaumcraft/client/WardenClientEffects$Sonic.class","thaumcraft/client/WardenClientEffects$Wisp.class","thaumcraft/client/GolemClientEffects.class","thaumcraft/client/GolemClientEffects$Sprite.class","thaumcraft/client/GolemClientEffects$Arc.class","thaumcraft/client/OriginalObjMesh.class","thaumcraft/client/OuterRoomRenderers.class","thaumcraft/client/R2EntityRenderers.class","assets/thaumcraft/textures/models/eldritch_warden.png","assets/thaumcraft/textures/models/hemis.obj","assets/thaumcraft/textures/models/sonic_frames.png")){try(var stream=ClientWardenVerification.class.getClassLoader().getResourceAsStream(resource)){if(stream==null)throw new AssertionError("Missing Warden payload "+resource);hashes.addProperty(resource,HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(stream.readAllBytes())));}}
        result.add("payload_sha256",hashes);result.add("checks",new Gson().toJsonTree(checks));result.addProperty("count",checks.size());result.addProperty("time",java.time.Instant.now().toString());result.addProperty("manual_acceptance","pending");result.addProperty("live_particle_motion","pending world fixture");Files.writeString(path.resolve("analysis/full_port/warden-client.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");mc.stop();
    }
    private static ModelPart find(String name,JsonObject parts,ModelPart root){var parent=parts.getAsJsonObject(name).get("parent");return(parent.isJsonNull()?root:find(parent.getAsString(),parts,root)).getChild(name);}
    private static Matrix4f transform(String name,JsonObject parts,JsonObject angles){var part=parts.getAsJsonObject(name);var parent=part.get("parent");var matrix=parent.isJsonNull()?new Matrix4f():transform(parent.getAsString(),parts,angles);var p=part.getAsJsonArray("pivot");var r=angles.getAsJsonArray(name);return matrix.translate(p.get(0).getAsFloat()/16,p.get(1).getAsFloat()/16,p.get(2).getAsFloat()/16).rotateZYX(r.get(2).getAsFloat(),r.get(1).getAsFloat(),r.get(0).getAsFloat());}
    private static void compare(List<float[]> actual,JsonArray original,Matrix4f matrix){if(actual.size()!=24)throw new AssertionError("Model cube must contain24 vertices");var remaining=new ArrayList<>(actual);for(var entry:original){var row=entry.getAsJsonArray();var position=new Vector3f(row.get(0).getAsFloat(),row.get(1).getAsFloat(),row.get(2).getAsFloat());matrix.transformPosition(position);float[] expected={position.x,position.y,position.z,row.get(3).getAsFloat(),row.get(4).getAsFloat()};boolean found=false;for(var it=remaining.iterator();it.hasNext();){var vertex=it.next();boolean same=true;for(int i=0;i<5;i++)same&=Math.abs(vertex[i]-expected[i])<2e-6;if(same){it.remove();found=true;break;}}if(!found)throw new AssertionError("Original Guardian/Warden position/UV missing: "+Arrays.toString(expected));}}
    private static void near(float actual,float expected,String message){if(!Float.isFinite(actual)||!Float.isFinite(expected)||Math.abs(actual-expected)>2e-6)throw new AssertionError(message+": "+actual+" / "+expected);}
    private static void require(boolean pass,String message,List<String> checks){if(!pass)throw new AssertionError(message);checks.add(message);}
    private static final class Capture implements VertexConsumer{final List<float[]> vertices=new ArrayList<>();int light;public VertexConsumer addVertex(float x,float y,float z){vertices.add(new float[]{x,y,z,0,0,0,0,0,0});return this;}public VertexConsumer setUv(float u,float v){var p=vertices.getLast();p[3]=u;p[4]=v;return this;}public VertexConsumer setColor(int r,int g,int b,int a){var p=vertices.getLast();p[5]=r;p[6]=g;p[7]=b;p[8]=a;return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){light=u|(v<<16);return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
    private ClientWardenVerification(){}
}
